-- Run once in the Supabase SQL editor. All content is private by default.
begin;
create table public.profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,display_name text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.folders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,parent_folder_id uuid,name text not null check(length(trim(name))>0),created_at timestamptz not null default now(),unique(id,user_id),foreign key(parent_folder_id,user_id) references public.folders(id,user_id),check(parent_folder_id is distinct from id));
create table public.documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,folder_id uuid,name text not null,file_type text not null default 'pdf',page_count integer not null default 0 check(page_count>=0),size_bytes bigint not null default 0 check(size_bytes>=0),storage_path text not null,status text not null default 'ready',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(id,user_id),foreign key(folder_id,user_id) references public.folders(id,user_id),check(split_part(storage_path,'/',1)=user_id::text));
create table public.document_pages(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page_number integer not null check(page_number>0),original_storage_path text,processed_storage_path text,rotation integer not null default 0,filter_settings jsonb not null default '{}',created_at timestamptz not null default now(),unique(document_id,page_number),unique(id,document_id));
create table public.ocr_results(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page_id uuid,language text not null default 'spa',extracted_text text not null default '',status text not null default 'pending' check(status in ('pending','complete','error')),created_at timestamptz not null default now(),foreign key(page_id,document_id) references public.document_pages(id,document_id) on delete cascade);
create table public.tags(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,unique(user_id,name));
create table public.document_tags(document_id uuid not null references public.documents(id) on delete cascade,tag_id uuid not null references public.tags(id) on delete cascade,primary key(document_id,tag_id));
create table public.share_links(id uuid primary key default gen_random_uuid(),document_id uuid not null,owner_id uuid not null references auth.users(id) on delete cascade,token_hash text not null unique,password_hash text,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now(),foreign key(document_id,owner_id) references public.documents(id,user_id) on delete cascade);
create table public.annotations(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,page_id uuid,annotation_type text not null,annotation_data jsonb not null,created_at timestamptz not null default now(),foreign key(page_id,document_id) references public.document_pages(id,document_id) on delete cascade);
create table public.processing_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,document_id uuid,operation text not null,status text not null default 'pending',error_message text,created_at timestamptz not null default now(),completed_at timestamptz,foreign key(document_id,user_id) references public.documents(id,user_id) on delete cascade);
create index folders_user_parent on public.folders(user_id,parent_folder_id);
create index documents_user_date on public.documents(user_id,updated_at desc);
create index documents_user_folder on public.documents(user_id,folder_id) where deleted_at is null;
create index ocr_document on public.ocr_results(document_id);
create index annotations_document on public.annotations(document_id);
create index jobs_user on public.processing_jobs(user_id,created_at desc);
create index share_document on public.share_links(document_id);
create index document_tags_tag on public.document_tags(tag_id);
do $$ declare t text;begin foreach t in array array['profiles','folders','documents','tags','processing_jobs'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy owner_access on public.%I for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t);end loop;end $$;
do $$ declare t text;begin foreach t in array array['document_pages','ocr_results','annotations'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy document_owner on public.%I for all to authenticated using (exists(select 1 from public.documents d where d.id=document_id and d.user_id=(select auth.uid()))) with check (exists(select 1 from public.documents d where d.id=document_id and d.user_id=(select auth.uid())))',t);end loop;end $$;
alter table public.document_tags enable row level security;
create policy tag_and_document_owner on public.document_tags for all to authenticated using (exists(select 1 from public.documents d where d.id=document_id and d.user_id=(select auth.uid())) and exists(select 1 from public.tags t where t.id=tag_id and t.user_id=(select auth.uid()))) with check (exists(select 1 from public.documents d where d.id=document_id and d.user_id=(select auth.uid())) and exists(select 1 from public.tags t where t.id=tag_id and t.user_id=(select auth.uid())));
alter table public.share_links enable row level security;
-- Future backend-only issuance and verification. No anonymous access to hashes.
create policy owner_read_links on public.share_links for select to authenticated using(owner_id=(select auth.uid()));
create policy owner_delete_links on public.share_links for delete to authenticated using(owner_id=(select auth.uid()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('documents','documents',false,52428800,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy private_document_storage on storage.objects for all to authenticated using(bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid()::text)) with check(bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid()::text));
create function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new;end $$;
create trigger touch_documents before update on public.documents for each row execute function public.touch_updated_at();
create trigger touch_profiles before update on public.profiles for each row execute function public.touch_updated_at();
commit;
